package vmcompat;
import java.util.*;import java.lang.classfile.*;import java.lang.constant.*;import java.lang.reflect.*;import java.nio.file.*;
public final class BreakdownTests {
    static void check(boolean x,String s){if(!x)throw new AssertionError(s);}
    static long val(Map<String,Object> m,String k){return ((Number)m.get(k)).longValue();}
    static void drain(){while(Breakdown.poll()!=null){}}
    public static void main(String[] args)throws Exception{
        check(Breakdown.ENABLED,"diagnostics enabled");drain();var l=new Breakdown.Lane(111);
        check(Boolean.TRUE.equals(l.boundary(1,1,100,10,0,true).get("first_partial")),"first partial");
        long p=l.enter(Breakdown.Scope.PZ_RENDER.ordinal(),110,12),c=l.enter(Breakdown.Scope.VP_WORLD.ordinal(),120,15);l.exit(c,150,25,false);l.exit(p,180,40,false);
        var row=l.boundary(1,1,200,50,1,true);long[] x=(long[])row.get("exclusive_ns"),in=(long[])row.get("inclusive_ns");check(Arrays.stream(x).sum()==100&&x[0]==30&&x[Breakdown.Scope.PZ_RENDER.ordinal()]==40&&x[Breakdown.Scope.VP_WORLD.ordinal()]==30,"exclusive partition");check(in[Breakdown.Scope.PZ_RENDER.ordinal()]==70&&in[Breakdown.Scope.VP_WORLD.ordinal()]==30,"nested inclusive not additive");check(val(row,"cpu_ns")==40&&val(row,"coverage_error_ns")==0,"thread CPU and coverage");
        var resource=new Breakdown.Lane(777);resource.boundary(1,1,1000,10,0,true);long rr=resource.enter(Breakdown.Scope.PZ_WORLD.ordinal(),1010,12);resource.resource(1040,1060);resource.exit(rr,1100,40,false);var resourceRow=resource.boundary(1,1,1110,45,1,true);check(((long[])resourceRow.get("exclusive_ns"))[Breakdown.Scope.RESOURCE.ordinal()]==20&&val(resourceRow,"coverage_error_ns")==0,"range duration reclassification without double count");
        long cross=l.enter(Breakdown.Scope.DISPLAY_UPDATE.ordinal(),210,55);var a=l.boundary(1,1,250,60,2,true);l.exit(cross,280,70,false);var b=l.boundary(1,1,300,75,3,true);check(((long[])a.get("exclusive_ns"))[Breakdown.Scope.DISPLAY_UPDATE.ordinal()]==40&&((long[])b.get("exclusive_ns"))[Breakdown.Scope.DISPLAY_UPDATE.ordinal()]==30,"scope clipped across boundary");
        var other=new Breakdown.Lane(222);other.boundary(1,1,100,-1,-1,false);long q=other.enter(Breakdown.Scope.MAIN_PREP.ordinal(),120,-1);other.exit(q,190,-1,false);var parallel=other.boundary(1,1,200,-1,-1,false);check(val(parallel,"wall_ns")==100&&parallel.get("cpu_ns")==null&&val(row,"wall_ns")==100,"parallel lane not added; CPU unsupported null");
        l.boundary(2,4,310,80,-1,false);long u=l.enter(Breakdown.Scope.PZ_UI.ordinal(),320,82);l.exit(u,330,85,false);var two=l.boundary(2,4,340,90,-1,false);var one=l.boundary(1,1,350,95,4,true);check(val(two,"wall_ns")==30&&val(one,"wall_ns")==50&&val(two,"stream_id")!=val(one,"stream_id"),"separate output windows");
        Object state=new Object(),drawer=new Object();Breakdown.populate(state);long gen=Breakdown.STATES.get(state).generation;viewpoint.core.Frame frame=new viewpoint.core.Frame();frame.number=7;frame.takenNanos=123;Breakdown.drawerCreated(drawer,frame);Breakdown.publish(state);
        Thread t=new Thread(()->{Breakdown.consume(state);long z=Breakdown.drawerBegin(drawer,frame);Breakdown.close(z);Breakdown.consume(state);long zz=Breakdown.drawerBegin(drawer,frame);Breakdown.close(zz);});t.start();t.join();check(Breakdown.STATES.get(state).uses.get()==2,"repeat consumption explicit");
        Breakdown.populate(state);check(Breakdown.STATES.get(state).generation!=gen,"reused state has new generation");frame.number=8;long bad=Breakdown.drawerBegin(drawer,frame);Breakdown.close(bad);check(Breakdown.LOCAL.get().links>0,"mutable snapshot mismatch unknown");Breakdown.drawerReleased(drawer);
        Object late=new Object();Breakdown.populate(late);long prep=Breakdown.open(Breakdown.Scope.MAIN_PREP.ordinal());Breakdown.publish(late);Breakdown.close(prep);check(Breakdown.LOCAL.get().depth==0,"late producer scope closes after publication");
        var missing=new Breakdown.Lane(333);missing.boundary(1,1,10,-1,-1,true);var acc=missing.streams.values().iterator().next();acc.expected=1;var mr=missing.boundary(1,1,20,-1,-1,true);check(val(mr,"missing_snapshots")==1&&!Boolean.TRUE.equals(mr.get("association_complete")),"missing snapshot explicit");
        var multi=new Breakdown.Lane(444);multi.boundary(1,1,10,-1,-1,true);multi.associate(1,21);multi.associate(1,22);check(multi.boundary(1,1,20,-1,-1,true).get("snapshot_status").equals("multiple"),"multiple snapshots explicit");
        drain();var overflow=new Breakdown.Lane(555);overflow.boundary(1,1,10,-1,-1,true);for(int i=0;i<4100;i++)Breakdown.offer(overflow,"test",Map.of());check(Breakdown.QUEUED.get()==4096&&Breakdown.LOST.get()>0,"queue bounded and nonblocking overflow");check(!Boolean.TRUE.equals(overflow.boundary(1,1,20,-1,-1,true).get("timing_complete")),"lost events mark incomplete");drain();
        reuseProbe();idleProbe();exceptionProbe();waitProbe();
        Path out=Path.of(System.getProperty("vmcompat.resultDir",System.getProperty("vmcompat.root")));Files.createDirectories(out);try(var sink=Breakdown.sink(out.resolve("synthetic.csv"))){sink.drain();}
        Files.writeString(out.resolve("breakdown-tests.json"),"{\"passed\":true,\"cases\":17,\"game_launched\":false}\n");System.out.println("BREAKDOWN TESTS PASS");
    }
    static void reuseProbe(){
        drain();Object[] states={new Object(),new Object(),new Object()},drawers={new Object(),new Object(),new Object()};viewpoint.core.Frame[] frames={new viewpoint.core.Frame(),new viewpoint.core.Frame(),new viewpoint.core.Frame()};
        for(int i=0;i<3;i++)Breakdown.drawerRegistered(drawers[i],frames[i]);
        Breakdown.LOCAL.get().links=0;
        for(int n=0;n<600;n++){int i=n%3;Breakdown.populate(states[i]);frames[i].number=n+100;frames[i].takenNanos=System.nanoTime();Breakdown.drawerQueued(drawers[i]);Breakdown.publish(states[i]);Breakdown.consume(states[i]);long token=Breakdown.drawerBegin(drawers[i],frames[i]);Breakdown.close(token);Breakdown.drawerReleased(drawers[i]);Breakdown.rendered(states[i]);check(Breakdown.LOCAL.get().links==0,"pooled publication must retain correct state/frame generation "+n);check(Breakdown.STATES.get(states[i]).expected.get()==1,"one snapshot expected per publication");drain();}
    }
    static void idleProbe(){drain();var idle=new Breakdown.Lane(999);long losses=Breakdown.LOST.get();for(int i=0;i<1_000_000;i++){long at=1_000_000L+i*100L;long t=idle.enter(Breakdown.Scope.INVOKE_QUEUE.ordinal(),at,at);idle.exit(t,at+50,at+40,false);}idle.flushIdle(101_000_000L,true);check(Breakdown.LOST.get()==losses&&Breakdown.QUEUED.get()<10,"million idle scopes aggregated without queue flood");long calls=0;Breakdown.Event e;while((e=Breakdown.poll())!=null)if(e.kind().equals("out_of_state_scopes"))calls+=Arrays.stream((long[])((Map<?,?>)e.data()).get("calls")).sum();check(calls==1_000_000,"idle aggregation preserves call count");}
    static void exceptionProbe()throws Exception{
        ClassDesc c=ClassDesc.of("vmcompat.tests.GeneratedScopeProbe");byte[] bytes=ClassFile.of().build(c,b->{b.withFlags(java.lang.reflect.Modifier.PUBLIC);b.withMethodBody("value",MethodTypeDesc.ofDescriptor("()I"),java.lang.reflect.Modifier.PUBLIC|java.lang.reflect.Modifier.STATIC,x->{x.bipush(42);x.ireturn();});b.withMethodBody("raise",MethodTypeDesc.ofDescriptor("(Ljava/lang/RuntimeException;)V"),java.lang.reflect.Modifier.PUBLIC|java.lang.reflect.Modifier.STATIC,x->{x.aload(0);x.athrow();});});
        bytes=DiagnosticTransform.rewrite("vmcompat/tests/GeneratedScopeProbe",bytes,Map.of("value",Breakdown.Scope.PZ_RENDER,"raise",Breakdown.Scope.VP_WORLD));check(ClassFile.of().verify(bytes).isEmpty(),"synthetic verifier");byte[] rewritten=bytes;
        Class<?> probe=new ClassLoader(BreakdownTests.class.getClassLoader()){Class<?> make(){return defineClass(c.displayName().equals("")?"":"vmcompat.tests.GeneratedScopeProbe",rewritten,0,rewritten.length);}}.make();
        check(probe.getMethod("value").invoke(null).equals(42),"return value unchanged");RuntimeException original=new IllegalArgumentException("same throwable");try{probe.getMethod("raise",RuntimeException.class).invoke(null,original);throw new AssertionError();}catch(InvocationTargetException e){check(e.getCause()==original,"exception identity unchanged");}check(Breakdown.LOCAL.get().depth==0,"exception cleanup closes stack");
    }
    static void waitProbe()throws Exception{Object monitor=new Object();synchronized(monitor){Breakdown.waitObject(monitor,1);}Thread.currentThread().interrupt();try{synchronized(monitor){Breakdown.waitObject(monitor,1);}throw new AssertionError();}catch(InterruptedException expected){check(!Thread.currentThread().isInterrupted(),"original interrupted status semantics");}check(Breakdown.LOCAL.get().depth==0,"wait exception cleanup");}
}
